import ghidra.app.decompiler.*;import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import ghidra.program.model.data.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public class settlement_TextBuilders extends GhidraScript{
public void run()throws Exception{
Function old=getFunctionAt(toAddr(0x562ac0));old.setCallingConvention("__fastcall");old.replaceParameters(Function.FunctionUpdateType.DYNAMIC_STORAGE_ALL_PARAMS,true,SourceType.USER_DEFINED,new ParameterImpl("group",CharDataType.dataType,currentProgram),new ParameterImpl("choice",CharDataType.dataType,currentProgram));
TreeMap<Long,Function>fs=new TreeMap<>();for(long va:new long[]{0x561b00,0x560cb0,0x561330,0x562ac0,0x560110,0x562bd0}){Function f=getFunctionAt(toAddr(va));fs.put(va,f);}for(Reference r:getReferencesTo(toAddr(0xa6c6c40))){Function f=getFunctionContaining(r.getFromAddress());if(f!=null)fs.put(f.getEntryPoint().getOffset(),f);}
DecompInterface dc=new DecompInterface();dc.toggleCCode(true);dc.openProgram(currentProgram);try(PrintWriter out=new PrintWriter(Files.newBufferedWriter(Path.of(getScriptArgs()[0]),StandardCharsets.UTF_8))){for(Function f:fs.values()){out.println("\n/* Function "+f.getEntryPoint()+" */");DecompileResults r=dc.decompileFunction(f,120,monitor);if(r.getDecompiledFunction()!=null)out.println(r.getDecompiledFunction().getC());else out.println(r.getErrorMessage());out.println("/* References:");for(Reference ref:getReferencesTo(f.getEntryPoint())){Function c=getFunctionContaining(ref.getFromAddress());out.println(ref.getFromAddress()+" caller "+(c==null?"none":c.getEntryPoint()));}out.println("*/");out.flush();println("Builder "+f.getEntryPoint());}}finally{dc.dispose();}
}}
